public long updateRto(long sampleMs) {
    // Проверка на корректность входных данных: RTT (Round-Trip Time) не может быть отрицательным
    if (sampleMs < 0) {
        throw new IllegalArgumentException("negative RTT sample");
    }

    // Если это первое измерение RTT (srtt еще не инициализировано, значение < 0)
    if (srtt < 0) {
        // Инициализируем сглаженное значение RTT (SRTT) первым замером
        srtt = sampleMs;
        // Инициализируем дисперсию RTT (RTTVAR) как половину первого замера
        // Это стандартная практика для начальной оценки вариативности
        rttvar = sampleMs / 2;
    } else {
        // Вычисляем абсолютную разницу между текущим сглаженным RTT и новым замером
        long delta = Math.abs(srtt - sampleMs);

        // Обновляем дисперсию RTT (RTTVAR) по формуле экспоненциального сглаживания:
        // RTTVAR = (3 * RTTVAR + |SRTT - RTT|) / 4
        // Это дает вес 3/4 предыдущему значению и 1/4 новому отклонению
        rttvar = (3 * rttvar + delta) / 4;

        // Обновляем сглаженное значение RTT (SRTT) по формуле экспоненциального сглаживания:
        // SRTT = (7 * SRTT + RTT) / 8
        // Это дает вес 7/8 предыдущему значению и 1/8 новому замеру
        srtt = (7 * srtt + sampleMs) / 8;
    }

    // Вычисляем таймаут повторной передачи (RTO) по формуле RFC 6298:
    // RTO = SRTT + max(G, 4 * RTTVAR)
    // где G — гранулярность таймера (минимальный шаг времени),
    // а 4 * RTTVAR учитывает возможную вариативность задержки
    long rto = srtt + Math.max(granularityMs, 4 * rttvar);

    // Ограничиваем RTO в разумных пределах:
    // Минимум 1000 мс (1 секунда) — чтобы избежать слишком частых повторных передач
    // Максимум 60000 мс (60 секунд) — чтобы не ждать слишком долго при плохом соединении
    return Math.min(Math.max(rto, 1000L), 60000L);
}
