public void Tick(double frameSeconds)
{
    // Ограничиваем время кадра максимальным значением, чтобы избежать
    // "спирали смерти" (spiral of death), когда система не успевает обрабатывать
    // слишком большие временные интервалы (например, после паузы или лага).
    if (frameSeconds > MaxFrame)
        frameSeconds = MaxFrame;

    // Добавляем прошедшее время кадра к аккумулятору.
    // Аккумулятор хранит остаток времени, который еще не был обработан
    // фиксированными шагами симуляции.
    _accumulator += frameSeconds;

    // Счетчик выполненных шагов симуляции в текущем кадре.
    var steps = 0;

    // Пока в аккумуляторе накопилось достаточно времени для выполнения
    // хотя бы одного полного шага симуляции (Step), выполняем шаги.
    while (_accumulator >= Step)
    {
        // Обновляем физический мир на фиксированный шаг времени.
        // Это обеспечивает детерминированность и стабильность физики.
        _world.Update(Step);

        // Вычитаем из аккумулятора время, которое было использовано для этого шага.
        _accumulator -= Step;

        // Увеличиваем счетчик шагов и проверяем, не превысили ли мы
        // максимальное количество шагов, разрешенных за один кадр.
        if (++steps >= MaxStepsPerFrame)
        {
            // Если достигнут лимит шагов, сбрасываем аккумулятор, чтобы
            // избежать накопления долга времени и потенциального зависания.
            _accumulator = 0;
            break;
        }
    }

    // Рендерим сцену, передавая интерполяционный коэффициент (alpha).
    // _accumulator / Step дает долю шага, которая еще не была обработана,
    // что позволяет плавно интерполировать позиции объектов между
    // последним и следующим состоянием физики для плавной визуализации.
    _renderer.Draw(_world, _accumulator / Step);
}
