// WriteFileAtomic атомарно записывает данные в файл по указанному пути.
// Атомарность достигается за счёт записи во временный файл с последующим
// переименованием его в целевой путь. Это гарантирует, что читатель файла
// никогда не увидит частично записанные данные.
func WriteFileAtomic(path string, data []byte, perm os.FileMode) error {
	// Создаём временный файл в той же директории, что и целевой файл.
	// Это важно, так как переименование (rename) работает атомарно только
	// в пределах одной файловой системы.
	tmp, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")
	if err != nil {
		return err
	}

	// Гарантируем удаление временного файла при выходе из функции,
	// если что-то пошло не так. Если всё пройдёт успешно, файл будет
	// переименован, и удаление не сработает (или проигнорирует ошибку).
	defer os.Remove(tmp.Name())

	// Записываем данные во временный файл.
	if _, err = tmp.Write(data); err == nil {
		// Синхронизируем данные с диском, чтобы убедиться, что они
		// действительно записаны, а не остались в буфере ОС.
		err = tmp.Sync()
	}

	// Закрываем временный файл. Если предыдущие операции прошли успешно,
	// сохраняем ошибку от Close (если она есть).
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}

	// Если ошибок не было, устанавливаем нужные права доступа для временного файла.
	// Это необходимо, так как os.CreateTemp создаёт файл с правами 0600,
	// а нам может потребоваться другой режим.
	if err == nil {
		err = os.Chmod(tmp.Name(), perm)
	}

	// Если на каком-то этапе возникла ошибка, возвращаем её.
	// Временный файл будет удалён defer-вызовом.
	if err != nil {
		return err
	}

	// Атомарно переименовываем временный файл в целевой путь.
	// На большинстве ОС это атомарная операция, поэтому читатель файла
	// либо увидит старое содержимое, либо новое, но никогда не смешанное.
	return os.Rename(tmp.Name(), path)
}
```

