```kotlin
fun blend(dst: Int, src: Int): Int {
    // Извлекаем альфа-канал (прозрачность) из источника (src).
    // Альфа хранится в старших 8 битах (биты 24-31).
    val a = src ushr 24

    // Если альфа источника равна 0, источник полностью прозрачен,
    // поэтому возвращаем целевой пиксель (dst) без изменений.
    if (a == 0) return dst

    // Если альфа источника равна 255, источник полностью непрозрачен,
    // поэтому возвращаем источник (src) без изменений.
    if (a == 255) return src

    // Вычисляем инвертированную альфу (1 - alpha), умноженную на 255.
    // Это нужно для взвешивания вклада целевого пикселя (dst).
    val inv = 255 - a

    // Смешиваем красный канал (bits 16-23):
    // (src_red * alpha + dst_red * inv_alpha) / 255
    val r = (((src shr 16) and 0xFF) * a + ((dst shr 16) and 0xFF) * inv) / 255

    // Смешиваем зеленый канал (bits 8-15):
    // (src_green * alpha + dst_green * inv_alpha) / 255
    val g = (((src shr 8) and 0xFF) * a + ((dst shr 8) and 0xFF) * inv) / 255

    // Смешиваем синий канал (bits 0-7):
    // (src_blue * alpha + dst_blue * inv_alpha) / 255
    val b = ((src and 0xFF) * a + (dst and 0xFF) * inv) / 255

    // Вычисляем итоговую альфу результата по формуле альфа-композиции:
    // out_alpha = src_alpha + dst_alpha * (1 - src_alpha)
    // Здесь используется целочисленная арифметика:
    // a + (dst_alpha * inv) / 255
    val outA = a + (dst ushr 24) * inv / 255

    // Собираем итоговый цвет в одно целое число (ARGB формат):
    // Альфа в старших битах, затем красный, зеленый и синий.
    return (outA shl 24) or (r shl 16) or (g shl 8) or b
}
