/// Парсит строку NMEA-предложения, проверяя контрольную сумму и разбивая данные на поля.
///
/// # Аргументы
/// * `line` — входная строка с NMEA-предложением (например, "$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47").
///
/// # Возвращаемое значение
/// * `Ok(Vec<&str>)` — вектор ссылок на подстроки, представляющие поля предложения (без префикса '$' и контрольной суммы).
/// * `Err(NmeaError)` — ошибка, если формат предложения некорректен или контрольная сумма не совпадает.
pub fn parse_nmea(line: &str) -> Result<Vec<&str>, NmeaError> {
    // Удаляем завершающие пробелы и символы переноса строки, чтобы избежать проблем при парсинге
    let line = line.trim_end();

    // Проверяем, что строка начинается с символа '$', который является обязательным префиксом для NMEA-предложений.
    // Если префикс отсутствует, возвращаем ошибку NoStart.
    let body = line.strip_prefix('$').ok_or(NmeaError::NoStart)?;

    // Разделяем тело предложения на полезную нагрузку (payload) и контрольную сумму (checksum).
    // Контрольная сумма всегда находится после последнего символа '*' в строке.
    // Если символ '*' отсутствует, возвращаем ошибку NoChecksum.
    let (payload, checksum) = body.rsplit_once('*').ok_or(NmeaError::NoChecksum)?;

    // Преобразуем шестнадцатеричную строку контрольной суммы в число типа u8.
    // Если преобразование не удалось (например, из-за некорректных символов), возвращаем ошибку BadChecksum.
    let expected = u8::from_str_radix(checksum, 16).map_err(|_| NmeaError::BadChecksum)?;

    // Вычисляем фактическую контрольную сумму полезной нагрузки.
    // Алгоритм XOR: побитовое исключающее ИЛИ всех байтов payload.
    let actual = payload.bytes().fold(0u8, |acc, b| acc ^ b);

    // Сравниваем вычисленную контрольную сумму с ожидаемой.
    // Если они не совпадают, возвращаем ошибку Mismatch с указанием ожидаемого и фактического значений.
    if actual != expected {
        return Err(NmeaError::Mismatch { expected, actual });
    }

    // Разбиваем полезную нагрузку на отдельные поля по разделителю ','.
    // Возвращаем вектор ссылок на подстроки, представляющие каждое поле.
    Ok(payload.split(',').collect())
}
```

