public void Enemy_Stays_Put_When_On_Target()
{
    // Создаём врага в позиции (5, 5)
    var enemy = new Enemy(new Vector2(5, 5));

    // Пытаемся двигаться к той же самой позиции (5, 5)
    // Так как направление движения равно нулевому вектору,
    // корректная реализация MoveTowards должна оставить позицию без изменений
    enemy.MoveTowards(new Vector2(5, 5), speed: 2f, dt: 0.016f);

    // Проверяем, что позиция осталась прежней
    Assert.Equal(new Vector2(5, 5), enemy.Position);
}
