    float distance = direction.Length();

    // Если расстояние до цели пренебрежимо мало (враг уже на месте),
    // не выполняем движение, чтобы избежать деления на ноль при нормализации
    if (distance < 0.0001f)
    {
        return;
    }

    // Нормализуем вектор направления, чтобы получить единичный вектор
    Vector2 normalizedDirection = direction / distance;

    // Вычисляем шаг движения за данный кадр
    Vector2 movement = normalizedDirection * speed * dt;

    // Если шаг движения больше, чем расстояние до цели,
    // перемещаемся точно в цель, чтобы не «перелететь» её
    if (movement.Length() >= distance)
    {
        Position = target;
    }
    else
    {
        // Иначе перемещаемся на рассчитанный шаг
        Position += movement;
    }
}
```

